"""Independent file/process/metadata checkpoint readback; no test execution."""
from pathlib import Path
import argparse,hashlib,importlib.util,json,zipfile
from native_E149_recovery_contract import R,FORMAL,read,sha,encoded,require,check_pins
T=R/'維護工具'
def module(name,path):
 spec=importlib.util.spec_from_file_location(name,path);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);return m
def verify(qp,master,chunk):
 q=read(qp);check_pins(q['source_pins']);check_pins(q['normal_product_pins']);require(q['status']=='unselected_summon51_selection_UI_controller_metadata_only','stage differs')
 validator=module('sun_weak_source_reader',T/'qualify-native-E149-summon51.py');c,k,prior,cov,proof,products=validator.validate(Path(q['compile_run'])/'cohort.json');require(q['metadata_products']==products and q['current_source_coverage']==cov and q['observed_actual_exit_code']==0 and q['observed_original_tool_chunk']==chunk and q['compiler_exit_codes']==[0]*18,'original compiler scope differs')
 process=module('sun_weak_original_process_reader',T/'readback-native-E149-eruption45-core.py');observations=[process.original_terminal(row) for row in [c['pipeline']]+[r['original_process'] for r in c['compiler_runs']]]
 initial=read(q['original_metadata_cohort']);require(sha(q['original_metadata_cohort'])==q['original_metadata_cohort_sha256'] and q['summon_pending_after_cast_action_bounded_seconds']==2,'initial source/pending policy differs');observations.extend(process.original_terminal(row) for row in [initial['pipeline']]+[r['original_process'] for r in initial['compiler_runs']])
 require((q['changed_runtime_files'],q['effective_overlay_files'],q['runtime_modules'],q['Rust_QA_files'],q['Java_files'],q['resolved_module_path_attributes'],q['original_nested_paths_preserved'],q['new_tests_written'],q['retained_skill_tests_written'],q['new_opt_in_original_resource_cases'])==(4,33,19,11,3,365,6,12,214,0),'source/case counts differ')
 require(all(q[x] for x in ['typed_summon_domain','explicit_nonmodal_selection_UI','full_inventory_owner_and_InputStamp_fence','server_controlled_selection_or_direct_grade','scoped_map_and_level_failure_after_cast_action','summon_effects_are_not_ACK','original_six_nested_targets_preserved','no_local_cost_damage_or_status_prediction','shared_audio_and_fragment_caps_unchanged']) and not any(q[x] for x in ['companion_commands_and_natural_lifetime_qualified','relative_graphics_hurt_binding_complete','optional_action0_speed_and_uint32_rollover_qualified','actual_GAME_overrides_observed','PEs_linked','outputs_executed','production_applied','canonical_registry_selected','GUI_verified','whole_goal_complete','old_source_success_transferred']) and q['tests_executed']==q['new_sessions']==q['desktop_inputs']==q['WAV_playbacks']==0,'execution/source scope differs')
 require(q['request_registered_ids']==[51] and q['summon_selection_count']==31 and cov['recognized_count']==64 and cov['missing_request_count']==116,'profile/coverage differs')
 require(sha(q['raw_archive'])==q['raw_archive_sha256'],'raw archive changed')
 with zipfile.ZipFile(q['raw_archive']) as z:require(len(z.namelist())==len(q['raw_archive_files']) and all(hashlib.sha256(z.read(Path(p).relative_to(R).as_posix())).hexdigest().upper()==h for p,h in q['raw_archive_files'].items()),'raw archive differs')
 rb=read(qp.with_name('readback.json'));require(rb['qualification']==str(qp) and rb['qualification_sha256']==sha(qp) and len(rb['after_files'])==8 and all(sha(R/n)==h for n,h in rb['after_files'].items()),'eight checkpoints differ')
 with zipfile.ZipFile(qp.with_name('before.zip')) as z:require(all(hashlib.sha256(z.read(n)).hexdigest().upper()==h for n,h in rb['before_files'].items()),'before checkpoint differs')
 w=read(R/'工作佇列.json');ref=w['current_E149_summon51_development'];require(ref['qualification']==str(qp) and ref['qualification_sha256']==sha(qp) and w['current_user_requested_goal']['test_execution_deferred_by_user'] and w['current_user_requested_goal']['desktop_automation_deferred_by_user'] and not w['active_workloads'] and not w['active_workload_sessions'] and not w['source_and_corresponding_QA_frozen'],'phase/current stage differs');require(sha(w['current_formal_reference_identity']['formal'])==FORMAL,'current formal JAR differs')
 require(q['current_fixture_binding_unchanged']==prior['current_fixture_binding_unchanged'] and q['current_formal_suite_unchanged']==prior['current_formal_suite_unchanged'] and q['canonical_registry_unchanged']==w['current_isolated_development']['candidates'],'registry/G06 differs')
 report=R.parent/'LiTo381-總開發報告.md';m=read(master);require(sha(report)==m['after_sha256'] and report.read_bytes()==master.parent.joinpath('after.md').read_bytes(),'master report differs');text=report.read_text('utf-8-sig');require(all(v in text for v in ['#51召喚術','226','64／剩116','selection','hurt','測試與桌面操作暫緩']),'report lacks current scope')
 result=dict(qualification=str(qp),qualification_sha256=sha(qp),original_process_observations=observations,metadata_commands=18,new_cases_written=12,tests_executed=0,normal_inputs_checked=1049,current_formal_JAR_unchanged=True,unchanged_registry_and_G06=True,eight_checkpoint_readback=str(qp.with_name('readback.json')),master_readback=str(master),master_report_sha256=sha(report),recognized_requests=64,remaining_request_ids=116,summon51_selection_UI_source_integrated=True,companion_lifetime_qualified=False,whole_goal_complete=False);qp.with_name('final-readback.json').write_bytes(encoded(result));print(json.dumps({k:v for k,v in result.items() if k!='original_process_observations'},ensure_ascii=False))
if __name__=='__main__':
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('qualification',type=Path);p.add_argument('--master-readback',type=Path,required=True);p.add_argument('--observed-original-tool-chunk',required=True);a=p.parse_args();verify(a.qualification,a.master_readback,a.observed_original_tool_chunk)
